import React, { useMemo, useState } from 'react';
import { View, Text, TextInput, Button, StyleSheet, FlatList, Linking } from 'react-native';

const lakes = [
  {
    id: 'järvi-1',
    name: 'Tuusulanjärvi',
    place: 'Tuusula',
    products: ['Gearspot SUP — Inflatable 10\'6"', 'Gearspot Sähköpyörä — City 1'],
    query: 'Tuusulanjärvi'
  },
  {
    id: 'järvi-2',
    name: 'Vesijärvi',
    place: 'Lahti',
    products: ['Gearspot SUP — Inflatable 10\'6"'],
    query: 'Vesijärvi'
  },
  {
    id: 'järvi-3',
    name: 'Päijänne',
    place: 'Asikkala',
    products: ['Gearspot SUP — Inflatable 10\'6"', 'Gearspot Sähköpyörä — City 1'],
    query: 'Päijänne'
  }
];

export default function MapSearchScreen() {
  const [search, setSearch] = useState('');

  const results = useMemo(() => {
    const normalized = search.trim().toLowerCase();
    if (!normalized) return lakes;
    return lakes.filter((lake) => lake.name.toLowerCase().includes(normalized) || lake.place.toLowerCase().includes(normalized));
  }, [search]);

  const openGoogleMaps = (query) => {
    const url = `https://www.google.com/maps/search/${encodeURIComponent(query)}`;
    Linking.openURL(url).catch(() => {
      alert('Ei voitu avata Google Mapsia.');
    });
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Etsi vuokrattavaa järven läheltä</Text>
      <TextInput
        style={styles.input}
        placeholder="Kirjoita järven nimi tai paikka"
        value={search}
        onChangeText={setSearch}
      />
      <FlatList
        data={results}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<Text style={styles.empty}>Ei hakutuloksia.</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.lakeName}>{item.name}</Text>
            <Text style={styles.place}>{item.place}</Text>
            <Text style={styles.products}>Tarjolla: {item.products.join(', ')}</Text>
            <Button title="Avaa Google Maps" onPress={() => openGoogleMaps(item.query)} />
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  title: { fontSize: 20, fontWeight: '700', marginBottom: 12 },
  input: { borderWidth: 1, borderColor: '#ccc', padding: 12, borderRadius: 8, marginBottom: 16 },
  card: { padding: 12, borderWidth: 1, borderColor: '#eee', borderRadius: 10, marginBottom: 12 },
  lakeName: { fontSize: 16, fontWeight: '700' },
  place: { marginBottom: 6, color: '#555' },
  products: { marginBottom: 8, color: '#333' },
  empty: { marginTop: 20, color: '#555' }
});
